const TEMPLATE_BASE64 = "";

function base64ToArrayBuffer(base64) {
    if (typeof window !== 'undefined' && typeof window.atob === 'function') {
        var binary_string = window.atob(base64);
        var len = binary_string.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
            bytes[i] = binary_string.charCodeAt(i);
        }
        return bytes.buffer;
    } else if (typeof atob === 'function') {
        var binary_string = atob(base64);
        var len = binary_string.length;
        var bytes = new Uint8Array(len);
        for (var i = 0; i < len; i++) {
            bytes[i] = binary_string.charCodeAt(i);
        }
        return bytes.buffer;
    } else if (typeof Buffer !== 'undefined') {
        return Buffer.from(base64, 'base64');
    }
}

const FUEL_DEFAULTS = {
  DO: { name: 'Dau Diesel (DO)', ncv: 43.00, density: 0.84, ef_co2_tj: 74100, ef_ch4_tj: 3.0, ef_n2o_tj: 0.6, unit: 'lit', ipcc_code: '1.A.2.h' },
  DIESEL: { name: 'Dau Diesel (DO)', ncv: 43.00, density: 0.84, ef_co2_tj: 74100, ef_ch4_tj: 3.0, ef_n2o_tj: 0.6, unit: 'lit', ipcc_code: '1.A.2.h' },
  FO: { name: 'Dau Fuel Oil (FO)', ncv: 40.40, density: 0.95, ef_co2_tj: 77400, ef_ch4_tj: 3.0, ef_n2o_tj: 0.6, unit: 'kg', ipcc_code: '1.A.2.h' },
  FUEL_OIL: { name: 'Dau Fuel Oil (FO)', ncv: 40.40, density: 0.95, ef_co2_tj: 77400, ef_ch4_tj: 3.0, ef_n2o_tj: 0.6, unit: 'kg', ipcc_code: '1.A.2.h' },
  GASOLINE: { name: 'Xang Mogas (RON 95/E5)', ncv: 44.30, density: 0.74, ef_co2_tj: 69300, ef_ch4_tj: 33.0, ef_n2o_tj: 3.2, unit: 'lit', ipcc_code: '1.A.3.b' },
  LPG: { name: 'Khi hoa long (LPG)', ncv: 47.30, density: 0.54, ef_co2_tj: 63100, ef_ch4_tj: 1.0, ef_n2o_tj: 0.1, unit: 'kg', ipcc_code: '1.A.2.h' },
  NATURAL_GAS: { name: 'Khi tu nhien (NG/CNG/LNG)', ncv: 48.00, density: 0.75, ef_co2_tj: 56100, ef_ch4_tj: 1.0, ef_n2o_tj: 0.1, unit: 'm3', ipcc_code: '1.A.2.h' },
  COAL: { name: 'Than da Antraxit', ncv: 26.28, density: 1.0, ef_co2_tj: 98300, ef_ch4_tj: 10.0, ef_n2o_tj: 1.5, unit: 'kg', ipcc_code: '1.A.2.h' },
  BIOMASS: { name: 'Nhien lieu sinh khoi (Biomass)', ncv: 15.60, density: 0.65, ef_co2_tj: 112000, ef_ch4_tj: 30.0, ef_n2o_tj: 4.0, unit: 'kg', ipcc_code: '1.A.2.h' }
};

function detectFuelInfo(act) {
  const name = String(act.sourceName || '').toLowerCase();
  const fuel = String(act.fuelId || act.energyType || act.efName || act.sourceType || '').toLowerCase();
  
  if (fuel.includes('biomass') || fuel.includes('mùn cưa') || fuel.includes('trấu')) return FUEL_DEFAULTS.BIOMASS;
  if (fuel.includes('cng') || fuel.includes('khí tự nhiên') || fuel.includes('natural_gas') || name.includes('re-melting') || name.includes('buồng đôi')) return FUEL_DEFAULTS.NATURAL_GAS;
  if (fuel.includes('lpg') || fuel.includes('gas') || name.includes('bếp ăn') || name.includes('khí hóa lỏng')) return FUEL_DEFAULTS.LPG;
  if (fuel.includes('fo') || fuel.includes('fuel_oil') || fuel.includes('dầu fo') || name.includes('anode')) return FUEL_DEFAULTS.FO;
  if (fuel.includes('xăng') || fuel.includes('gasoline') || fuel.includes('ron')) return FUEL_DEFAULTS.GASOLINE;
  if (fuel.includes('than') || fuel.includes('coal') || fuel.includes('antraxit')) return FUEL_DEFAULTS.COAL;
  if (fuel.includes('diesel') || fuel.includes('do') || fuel.includes('dầu do') || name.includes('máy phát điện') || name.includes('genset') || name.includes('xe nâng')) return FUEL_DEFAULTS.DO;

  return FUEL_DEFAULTS.DO;
}

function cleanDisplayName(name, fuelName) {
  if (!name) return fuelName || 'Thiết bị';
  return name;
}

function resolveGridEFInfo(yearInput) {
  if (typeof window !== 'undefined' && typeof window.getGridElectricityEFInfo === 'function') {
    return window.getGridElectricityEFInfo(yearInput);
  }
  let yr = 2026;
  if (yearInput !== undefined && yearInput !== null && yearInput !== '') {
    const parsed = parseInt(String(yearInput).replace(/\D/g, ''), 10);
    if (!isNaN(parsed) && parsed >= 2000 && parsed <= 2100) yr = parsed;
  } else if (typeof localStorage !== 'undefined') {
    try {
      const saved = localStorage.getItem('gs_active_report_year');
      if (saved) {
        const parsed = parseInt(saved, 10);
        if (!isNaN(parsed) && parsed >= 2000 && parsed <= 2100) yr = parsed;
      }
    } catch (e) {}
  }
  if (yr <= 2022) {
    return {
      year: yr,
      factor: 0.6766,
      factorComma: '0,6766',
      doc: 'Công văn số 1726/BĐKH-TTBVTOD ngày 30/12/2023 với hệ số chính thức là 0,6766 tCO₂/MWh',
      shortDoc: 'CV 1726/BĐKH-TTBVTOD (0,6766 tCO₂/MWh)'
    };
  }
  if (yr === 2023) {
    return {
      year: yr,
      factor: 0.6592,
      factorComma: '0,6592',
      doc: 'Công bố của Cục Biến đổi khí hậu năm 2023 với hệ số chính thức là 0,6592 tCO₂/MWh',
      shortDoc: 'Cục BĐKH 2023 (0,6592 tCO₂/MWh)'
    };
  }
  return {
    year: yr,
    factor: 0.6187,
    factorComma: '0,6187',
    doc: 'Công văn số 11232/BNNMT-BĐKH ngày 30/9/2026 với hệ số chính thức là 0,6187 tCO₂/MWh',
    shortDoc: 'Công văn số 11232/BNNMT-BĐKH ngày 30/9/2026 (0,6187 tCO₂/MWh)'
  };
}

const WordExport = {
  resolveGridEFInfo,
  groupActivities(activities, reportYear) {
    const efInfo = resolveGridEFInfo(reportYear);
    const stationaryMap = new Map();
    const mobileMap = new Map();
    const scope2Map = new Map();
    const fugitiveMap = new Map();
    const pcccMap = new Map();
    const wastewaterMap = new Map();
    const tbl317Map = new Map();
    const tbl318Map = new Map();

    let sumGHG = 0;
    let sumSquares = 0;
    let sumBiogenic_tco2 = 0;

    let ch4Gwp = 28;
    let n2oGwp = 265;
    try {
      const uStr = localStorage.getItem('gs_current_user');
      const users = JSON.parse(localStorage.getItem('gs_users') || '[]');
      const curUser = users.find(x => x.username === uStr);
      if (curUser && curUser.company && curUser.company.ipccAR === 'AR6-100') {
        ch4Gwp = 27.9;
        n2oGwp = 273;
      } else if (curUser && curUser.company && curUser.company.ipccAR === 'AR4-100') {
        ch4Gwp = 25;
        n2oGwp = 298;
      }
    } catch(e) {}

    if (!Array.isArray(activities)) {
      activities = [];
    }

    activities.forEach((act) => {
      const amount = parseFloat(act.amount) || 0;
      if (amount <= 0) return;

      const unit = String(act.unit || '').trim().toLowerCase();
      const name = String(act.sourceName || 'Thiết bị').trim();
      const nameLower = name.toLowerCase();
      const type = String(act.sourceType || '').trim();
      const typeLower = type.toLowerCase();
      const group = String(act.sourceGroup || '').trim();
      const groupLower = group.toLowerCase();
      const cat = String(act.category || '').trim();
      const catLower = cat.toLowerCase();
      const energyType = String(act.energyType || '').toUpperCase();
      const scopeType = String(act.scopeType || '').toUpperCase();

      const isBiomass = Boolean(act.isBiomass || act.is_biomass || nameLower.includes('biomass'));

      // 1. Phân loại Nước thải sinh hoạt (Bể tự hoại)
      const isWastewater = (energyType === 'WASTEWATER' || typeLower === 'nước thải' ||
          nameLower.includes('tự hoại') || nameLower.includes('nước thải') || 
          nameLower.includes('xử lý nước') || nameLower.includes('bod') || nameLower.includes('septic'));

      // 2. Phân loại Môi chất lạnh (Chiller / Điều hòa)
      const isRefrigerant = !isWastewater && (energyType === 'REFRIGERANT' || energyType === 'HFC' ||
          Boolean(act.refName) || nameLower.includes('chiller') || nameLower.includes('điều hòa') ||
          nameLower.includes('vrv') || nameLower.includes('gas lạnh') || nameLower.includes('môi chất') ||
          nameLower.includes('r134a') || nameLower.includes('r410a') || nameLower.includes('r32') || nameLower.includes('r123'));

      // 3. Phân loại Bình PCCC CO2
      const isPccc = !isWastewater && !isRefrigerant && (
          nameLower.includes('bình chữa cháy') || nameLower.includes('pccc') ||
          nameLower.includes('co2 xách tay') || nameLower.includes('mt3') || nameLower.includes('mt5'));

      // 4. Phân loại Điện lưới Scope 2 (Đơn vị kWh / MWh, loại trừ thiết bị đốt nhiên liệu)
      const isElectricity = !isWastewater && !isRefrigerant && !isPccc && (
          unit === 'kwh' || unit === 'mwh' || scopeType === 'SCOPE_2' || energyType === 'ELECTRICITY' ||
          type === 'Tiêu thụ điện' || type === 'Tiêu thụ điện lưới' || typeLower === 'tiêu thụ điện' || typeLower === 'tiêu thụ điện lưới' || typeLower === 'điện mua vào' ||
          catLower === 'điện mua vào' || catLower === 'tiêu thụ điện'
      ) && !nameLower.includes('máy phát điện') && !nameLower.includes('dầu do') && energyType !== 'DIESEL';

      // 5. Phân loại Quá trình công nghiệp (Scope 1 IPPU)
      const isProcess = !isWastewater && !isRefrigerant && !isPccc && !isElectricity && (
          act.isProcessEmission === 'true' || 
          typeLower.includes('quá trình công nghiệp') || 
          catLower.includes('công nghiệp') || 
          typeLower.includes('thổi oxy') || 
          typeLower.includes('lò hồ quang điện trong luyện thép') || 
          typeLower.includes('luyện thép') ||
          nameLower.includes('ippu') || 
          nameLower.includes('quá trình luyện thép')
      );

      // 6. Phân loại Nguồn đốt di động (Scope 1 Mobile)
      const isMobile = !isWastewater && !isRefrigerant && !isPccc && !isElectricity && !isProcess && (
          typeLower === 'đốt cháy động' || groupLower === 'nguồn đốt di động' ||
          nameLower.includes('xe nâng') || nameLower.includes('xe tải') ||
          nameLower.includes('ô tô') || nameLower.includes('phương tiện')
      );

      // Uncertainty defaults
      let u_ad = 0.05;
      if (act.measure === 'Đo liên tục' || unit === 'kwh') u_ad = 0.02;
      else if (act.measure === 'Ước tính kế toán tài chính') u_ad = 0.10;
      else if (act.reliability === 'Không có bằng chứng rõ ràng') u_ad = 0.15;

      if (isWastewater) {
        const key = name;
        const ef_ww = act.finalFactor ? parseFloat(act.finalFactor) : 0.18;
        const tow = act.tow ? parseFloat(act.tow) : amount;
        const t_co2e = parseFloat(act.co2e) ? (parseFloat(act.co2e) / 1000) : ((tow * ef_ww * ch4Gwp) / 1000);
        if (!wastewaterMap.has(key)) {
          wastewaterMap.set(key, {
            name: name,
            tow_sum: 0,
            s_sum: 0,
            r_sum: 0,
            ef_ww: ef_ww,
            t_co2e_sum: 0
          });
        }
        const item = wastewaterMap.get(key);
        item.tow_sum += tow;
        item.t_co2e_sum += t_co2e;

        const k317 = `4.D:::${name}:::CH4`;
        if (!tbl317Map.has(k317)) {
          tbl317Map.set(k317, { name: name, gas: 'CH4', u_val: (u_ad * 100).toFixed(2) + '%', ref: 'IPCC 2006, Tap 5, Chuong 6' });
        }
        const k318 = `4.D:::${name}:::CH4`;
        if (!tbl318Map.has(k318)) {
          tbl318Map.set(k318, { name: name, gas: 'CH4', u_val: '30,00%', ref: 'QD 2626/QD-BTNMT' });
        }
        const uSource = Math.sqrt(Math.pow(u_ad, 2) + Math.pow(0.30, 2));
        sumSquares += Math.pow(uSource * t_co2e, 2);
        sumGHG += t_co2e;

      } else if (isRefrigerant) {
        let refGas = act.refName || 'R-134a';
        const refLower = refGas.toLowerCase();
        let gwp = act.finalFactor ? parseFloat(act.finalFactor) : 1430;
        if (nameLower.includes('r123') || refLower.includes('r123') || refLower.includes('123')) { refGas = 'HCFC-123'; gwp = 90.4; }
        else if (nameLower.includes('r410a') || refLower.includes('r410a') || refLower.includes('410')) { refGas = 'R-410A'; gwp = 2088; }
        else if (nameLower.includes('r32') || refLower.includes('r32') || refLower.includes('32')) { refGas = 'R-32'; gwp = 675; }
        else if (nameLower.includes('r134a') || refLower.includes('r134a') || refLower.includes('134')) { refGas = 'R-134a'; gwp = 1430; }

        const key = `${name}:::${refGas}`;
        const inputAmount = amount;
        let t_co2e = 0;
        let leak_ton = 0;
        let charge_ton = act.charge_kg ? parseFloat(act.charge_kg) / 1000 : 0.120;
        let leak_rate = 3.0;

        if (parseFloat(act.co2e)) {
          t_co2e = parseFloat(act.co2e) / 1000;
          leak_ton = t_co2e / gwp;
          if (inputAmount >= 50) {
            charge_ton = inputAmount / 1000;
            leak_rate = charge_ton > 0 ? (leak_ton / charge_ton) * 100 : 3.0;
          } else {
            charge_ton = Math.max(0.120, (leak_ton / 0.03));
            leak_rate = charge_ton > 0 ? (leak_ton / charge_ton) * 100 : 3.0;
          }
        } else {
          if (inputAmount >= 50) {
            charge_ton = inputAmount / 1000;
            leak_rate = 3.0;
            leak_ton = charge_ton * 0.03;
            t_co2e = leak_ton * gwp;
          } else {
            leak_ton = inputAmount / 1000;
            charge_ton = Math.max(0.120, (leak_ton / 0.03));
            leak_rate = charge_ton > 0 ? (leak_ton / charge_ton) * 100 : 3.0;
            t_co2e = leak_ton * gwp;
          }
        }

        if (!fugitiveMap.has(key)) {
          fugitiveMap.set(key, {
            name: name,
            ref_gas: refGas,
            charge_ton: charge_ton,
            leak_rate: leak_rate,
            leak_ton: 0,
            gwp: gwp,
            t_co2e_sum: 0,
            amount_sum: 0,
            location: act.location || 'Phòng cơ điện trung tâm',
            start_date: act.startDate || '2020',
            capacity: act.capacity || '546.000 BTU/h (160 kW)',
            charge_kg: Math.round(charge_ton * 1000)
          });
        }
        const item = fugitiveMap.get(key);
        item.t_co2e_sum += t_co2e;
        item.amount_sum += inputAmount;
        item.leak_ton += leak_ton;
        if (item.charge_ton > 0) {
          item.leak_rate = (item.leak_ton / item.charge_ton) * 100;
        }

        const k317 = `2.F:::${name}:::HFCs`;
        if (!tbl317Map.has(k317)) {
          tbl317Map.set(k317, { name: name, gas: 'HFCs', u_val: (u_ad * 100).toFixed(2) + '%', ref: 'IPCC 2006, Tap 3, Chuong 7' });
        }
        const k318 = `2.F:::${name}:::HFCs`;
        if (!tbl318Map.has(k318)) {
          tbl318Map.set(k318, { name: name, gas: 'HFCs', u_val: '15,00%', ref: 'IPCC 2006, Tap 3, Chuong 7' });
        }
        const uSource = Math.sqrt(Math.pow(u_ad, 2) + Math.pow(0.15, 2));
        sumSquares += Math.pow(uSource * t_co2e, 2);
        sumGHG += t_co2e;

      } else if (isPccc) {
        const key = name;
        const weight_kg = amount;
        const quantity = Math.max(1, Math.round(weight_kg / 5));
        const leak_rate = 5;
        const t_co2 = parseFloat(act.co2e) ? parseFloat(act.co2e) / 1000 : (weight_kg * 0.05 / 1000);

        if (!pcccMap.has(key)) {
          pcccMap.set(key, {
            name: name,
            weight_kg: weight_kg,
            quantity: quantity,
            leak_rate: leak_rate,
            t_co2: t_co2
          });
        } else {
          const item = pcccMap.get(key);
          item.weight_kg += weight_kg;
          item.quantity += quantity;
          item.t_co2 += t_co2;
        }

        const k317 = `2.D.4:::${name}:::CO2`;
        if (!tbl317Map.has(k317)) {
          tbl317Map.set(k317, { name: name, gas: 'CO2', u_val: '5,00%', ref: 'IPCC 2006, Tap 3, Chuong 7' });
        }
        const k318 = `2.D.4:::${name}:::CO2`;
        if (!tbl318Map.has(k318)) {
          tbl318Map.set(k318, { name: name, gas: 'CO2', u_val: '5,00%', ref: 'IPCC 2006, Tap 3, Chuong 7' });
        }
        const uSource = Math.sqrt(Math.pow(0.05, 2) + Math.pow(0.05, 2));
        sumSquares += Math.pow(uSource * t_co2, 2);
        sumGHG += t_co2;

      } else if (isElectricity) {
        // Scope 2: Dien mua ngoai (Ap dung he so phat thai luoi dien theo nam bao cao)
        const rawActEf = act.finalFactor ? parseFloat(act.finalFactor) : 0;
        const isStandardGridEf = (!rawActEf || Math.abs(rawActEf - 0.6766) < 0.0001 || Math.abs(rawActEf - 0.6592) < 0.0001 || Math.abs(rawActEf - 0.6187) < 0.0001);
        const actYear = (act.date && String(act.date).length >= 4) ? String(act.date).slice(0, 4) : null;
        const actEfInfo = reportYear ? efInfo : (actYear ? resolveGridEFInfo(actYear) : efInfo);
        const efGridVal = (reportYear || isStandardGridEf) ? actEfInfo.factor : rawActEf;
        const amountKwh = (unit === 'mwh') ? (amount * 1000) : amount;
        const t_co2e = (reportYear || isStandardGridEf || !parseFloat(act.co2e))
          ? ((amountKwh * efGridVal) / 1000)
          : (parseFloat(act.co2e) / 1000);
        const key = `${name}:::${efGridVal}`;

        if (!scope2Map.has(key)) {
          scope2Map.set(key, {
            name: name,
            amount_sum: 0,
            ef_grid: efGridVal,
            t_co2e_sum: 0
          });
        }
        const item = scope2Map.get(key);
        item.amount_sum += amountKwh;
        item.t_co2e_sum += t_co2e;

        const k317 = `2.A:::${name}:::CO2`;
        if (!tbl317Map.has(k317)) {
          tbl317Map.set(k317, { name: name, gas: 'CO2', u_val: '2,00%', ref: 'DLVN 297:2016' });
        }
        const k318 = `2.A:::${name}:::CO2`;
        if (!tbl318Map.has(k318)) {
          tbl318Map.set(k318, { name: name, gas: 'CO2', u_val: '5,00%', ref: efInfo.doc });
        }
        const uSource = Math.sqrt(Math.pow(0.02, 2) + Math.pow(0.05, 2));
      } else if (isProcess) {
        // Scope 1: Quá trình công nghiệp (IPPU - Luyện thép / Hóa chất)
        const rawEf = act.finalFactor ? parseFloat(act.finalFactor) : 60;
        const ef_process = rawEf;
        const calc_tco2e = parseFloat(act.co2e) ? (parseFloat(act.co2e) / 1000) : ((amount * ef_process) / 1000);
        const t_co2e = calc_tco2e;
        const processFuel = 'Quá trình công nghệ (IPPU)';
        const targetUnit = act.unit || 'tấn';
        const key = `${name}:::${processFuel}:::${targetUnit}`;

        if (!stationaryMap.has(key)) {
          stationaryMap.set(key, {
            name: name,
            fuel: processFuel,
            unit: targetUnit,
            amount_sum: 0,
            density: 1,
            consumption_gg_sum: 0,
            ncv: 0,
            tj_sum: 0,
            ef_co2: ef_process,
            t_co2_sum: 0,
            ef_ch4: 0,
            t_ch4_sum: 0,
            ef_n2o: 0,
            t_n2o_sum: 0,
            t_co2e_sum: 0
          });
        }
        const item = stationaryMap.get(key);
        item.amount_sum += amount;
        item.t_co2_sum += t_co2e;
        item.t_co2e_sum += t_co2e;

        const k317 = `2.C.1:::${name}:::CO2`;
        if (!tbl317Map.has(k317)) {
          tbl317Map.set(k317, { name: name, gas: 'CO2', u_val: '5,00%', ref: 'IPCC 2006, Tap 3, Chuong 4 (Luyen thep)' });
        }
        const k318 = `2.C.1:::${name}:::CO2`;
        if (!tbl318Map.has(k318)) {
          tbl318Map.set(k318, { name: name, gas: 'CO2', u_val: '5,00%', ref: 'QD 2626/QD-BTNMT' });
        }
        const uSource = Math.sqrt(Math.pow(0.05, 2) + Math.pow(0.05, 2));
        sumSquares += Math.pow(uSource * t_co2e, 2);
        sumGHG += t_co2e;

      } else {
        // Scope 1: Dot nhien lieu (Co dinh hoac Di dong)
        const fuelDef = detectFuelInfo(act);
        const targetMap = isMobile ? mobileMap : stationaryMap;
        const targetUnit = act.unit || fuelDef.unit;

        const density = fuelDef.density;
        const ncv = fuelDef.ncv;
        const consumption_gg = (amount * (targetUnit.toLowerCase() === 'kg' ? 1 : density)) / 1000000;
        const tj = consumption_gg * ncv;
        const ef_co2_tj = fuelDef.ef_co2_tj;
        const ef_ch4_tj = fuelDef.ef_ch4_tj;
        const ef_n2o_tj = fuelDef.ef_n2o_tj;

        let bioCo2 = 0;
        if (isBiomass) {
          bioCo2 = parseFloat(act.biogenicCo2) ? (parseFloat(act.biogenicCo2) / 1000) : (parseFloat(act.co2e) ? parseFloat(act.co2e) / 1000 : ((tj * ef_co2_tj) / 1000));
          sumBiogenic_tco2 += bioCo2;
        }
        const t_co2 = isBiomass ? 0 : ((tj * ef_co2_tj) / 1000);
        const t_ch4 = (tj * ef_ch4_tj) / 1000;
        const t_n2o = (tj * ef_n2o_tj) / 1000;
        const calc_tco2e = t_co2 + (t_ch4 * ch4Gwp) + (t_n2o * n2oGwp);
        const t_co2e = isBiomass ? ((t_ch4 * ch4Gwp) + (t_n2o * n2oGwp)) : (parseFloat(act.co2e) ? parseFloat(act.co2e) / 1000 : calc_tco2e);

        const fuelLabel = fuelDef.name + (isBiomass ? " (Sinh học / Biomass)" : "");
        const displayName = cleanDisplayName(name, fuelDef.name);
        const key = `${displayName}:::${fuelLabel}:::${targetUnit}`;

        if (!targetMap.has(key)) {
          targetMap.set(key, {
            name: displayName,
            fuel: fuelLabel,
            unit: targetUnit,
            amount_sum: 0,
            density: density,
            consumption_gg_sum: 0,
            ncv: ncv,
            tj_sum: 0,
            ef_co2: ef_co2_tj,
            t_co2_sum: 0,
            ef_ch4: ef_ch4_tj,
            t_ch4_sum: 0,
            ef_n2o: ef_n2o_tj,
            t_n2o_sum: 0,
            t_co2e_sum: 0
          });
        }
        const item = targetMap.get(key);
        item.amount_sum += amount;
        item.consumption_gg_sum += consumption_gg;
        item.tj_sum += tj;
        item.t_co2_sum += t_co2;
        item.t_ch4_sum += t_ch4;
        item.t_n2o_sum += t_n2o;
        item.t_co2e_sum += t_co2e;

        const ipcc = fuelDef.ipcc_code;
        const k317 = `${displayName}:::CO2, CH4, N2O`;
        if (!tbl317Map.has(k317)) {
          tbl317Map.set(k317, { name: displayName, gas: 'CO2, CH4, N2O', u_val: (u_ad * 100).toFixed(2) + '%', ref: 'IPCC 2006, Tap 2, Chuong 2' });
        }
        const k318 = `${displayName}:::CO2`;
        if (!tbl318Map.has(k318)) {
          tbl318Map.set(k318, { name: displayName, gas: 'CO2', u_val: '5,00%', ref: 'QD 2626/QD-BTNMT' });
        }
        const uSource = Math.sqrt(Math.pow(u_ad, 2) + Math.pow(0.05, 2));
        sumSquares += Math.pow(uSource * t_co2e, 2);
        sumGHG += t_co2e;
      }
    });

    const total_uncertainty = sumGHG > 0 ? Math.sqrt(sumSquares) / sumGHG : 0;

    // Chuyen Map thanh mang cho docxtemplater
    const scope1_stationary = Array.from(stationaryMap.values()).map((row, idx) => ({
      i: idx + 1,
      name: row.name,
      fuel: row.fuel,
      consumption_original: row.amount_sum.toLocaleString('vi-VN'),
      unit: row.unit,
      density: row.density !== 1 ? row.density.toString().replace('.', ',') : '-',
      consumption_gg: row.consumption_gg_sum > 0 ? row.consumption_gg_sum.toFixed(5).replace('.', ',') : '-',
      ncv: row.ncv > 0 ? row.ncv.toString().replace('.', ',') : '-',
      tj: row.tj_sum > 0 ? row.tj_sum.toFixed(4).replace('.', ',') : '-',
      ef_co2: row.ef_co2 > 0 ? row.ef_co2.toLocaleString('vi-VN') : '-',
      t_co2: row.t_co2_sum > 0 ? row.t_co2_sum.toFixed(2).replace('.', ',') : '-',
      ef_ch4: row.ef_ch4 > 0 ? row.ef_ch4.toLocaleString('vi-VN') : '-',
      t_ch4: row.t_ch4_sum > 0 ? row.t_ch4_sum.toFixed(4).replace('.', ',') : '-',
      ef_n2o: row.ef_n2o > 0 ? row.ef_n2o.toLocaleString('vi-VN') : '-',
      t_n2o: row.t_n2o_sum > 0 ? row.t_n2o_sum.toFixed(5).replace('.', ',') : '-',
      t_co2e: row.t_co2e_sum.toFixed(2).replace('.', ',')
    }));

    const scope1_mobile = Array.from(mobileMap.values()).map((row, idx) => ({
      i: idx + 1,
      name: row.name,
      vehicle_info: row.name,
      fuel: row.fuel,
      consumption_original: row.amount_sum.toLocaleString('vi-VN'),
      unit: row.unit || 'lít',
      desc: 'Nhiên liệu vận tải nội bộ',
      density: row.density !== 1 ? row.density.toString().replace('.', ',') : '-',
      consumption_gg: row.consumption_gg_sum > 0 ? row.consumption_gg_sum.toFixed(5).replace('.', ',') : '-',
      ncv: row.ncv > 0 ? row.ncv.toString().replace('.', ',') : '-',
      tj: row.tj_sum > 0 ? row.tj_sum.toFixed(4).replace('.', ',') : '-',
      ef_co2: row.ef_co2 > 0 ? row.ef_co2.toLocaleString('vi-VN') : '-',
      t_co2: row.t_co2_sum > 0 ? row.t_co2_sum.toFixed(2).replace('.', ',') : '-',
      ef_ch4: row.ef_ch4 > 0 ? row.ef_ch4.toLocaleString('vi-VN') : '-',
      t_ch4: row.t_ch4_sum > 0 ? row.t_ch4_sum.toFixed(4).replace('.', ',') : '-',
      ef_n2o: row.ef_n2o > 0 ? row.ef_n2o.toLocaleString('vi-VN') : '-',
      t_n2o: row.t_n2o_sum > 0 ? row.t_n2o_sum.toFixed(5).replace('.', ',') : '-',
      t_co2e: row.t_co2e_sum.toFixed(2).replace('.', ',')
    }));

    const scope1_combustion = scope1_stationary.concat(scope1_mobile);

    const scope1_fugitive = Array.from(fugitiveMap.values()).map((row, idx) => ({
      i: idx + 1,
      name: row.name,
      location: row.location || 'Phòng cơ điện trung tâm',
      start_date: row.start_date || '2020',
      ref_gas: row.ref_gas,
      capacity: row.capacity || '546.000 BTU/h (160 kW)',
      charge_kg: (row.charge_kg || Math.round(row.charge_ton * 1000) || 120).toLocaleString('vi-VN'),
      charge_ton: row.charge_ton.toFixed(3).replace('.', ','),
      leak_rate: (row.leak_rate || 3).toFixed(2).replace('.', ','),
      leak_ton: row.leak_ton.toFixed(4).replace('.', ','),
      gwp: row.gwp > 0 ? row.gwp.toLocaleString('vi-VN') : '-',
      amount: row.amount_sum.toLocaleString('vi-VN'),
      time: 'Định kỳ hàng năm',
      t_co2e: row.t_co2e_sum.toFixed(2).replace('.', ',')
    }));

    const scope1_pccc = Array.from(pcccMap.values()).map(row => ({
      name: row.name,
      weight_kg: row.weight_kg.toLocaleString('vi-VN'),
      quantity: row.quantity.toString(),
      leak_rate: row.leak_rate.toString(),
      t_co2: row.t_co2.toFixed(4).replace('.', ',')
    }));

    let wwMeta = {};
    try {
      if (typeof localStorage !== 'undefined') {
        wwMeta = JSON.parse(localStorage.getItem('gs_wastewater_params') || '{}');
      }
    } catch(e) {}

    let compInfo = {};
    try {
      if (typeof localStorage !== 'undefined') {
        compInfo = JSON.parse(localStorage.getItem('gs_v2_company') || '{}');
      }
    } catch(e) {}

    const ww_emp = parseFloat(wwMeta.emp) || parseFloat(compInfo.employees) || parseFloat(compInfo.employeeCount) || 450;
    const ww_hours = parseFloat(wwMeta.hours) || 8;
    const ww_days = parseFloat(wwMeta.days) || 300;
    const ww_bod_conc = 40;
    const ww_bod_per_person_year = (ww_bod_conc * 0.001 * (ww_hours / 24) * ww_days);
    const ww_i_factor = parseFloat(wwMeta.iFactor) || 1.0;

    let totalWwTow = Array.from(wastewaterMap.values()).reduce((sum, r) => sum + r.tow_sum, 0);
    if (totalWwTow <= 0) {
      totalWwTow = ww_emp * ww_bod_per_person_year * ww_i_factor;
    }

    const scope1_wastewater = Array.from(wastewaterMap.values()).map(row => ({
      name: row.name,
      tow: Math.round(row.tow_sum).toLocaleString('vi-VN'),
      s: '0',
      r: '0',
      ef_ww: typeof row.ef_ww === 'number' ? row.ef_ww.toString().replace('.', ',') : '0,18',
      ch4_kg: (row.t_co2e_sum * 1000 / ch4Gwp).toFixed(2).replace('.', ','),
      gwp: ch4Gwp.toString().replace('.', ','),
      t_co2e: row.t_co2e_sum.toFixed(2).replace('.', ',')
    }));

    if (scope1_wastewater.length === 0) {
      const defTow = totalWwTow;
      const defEf = 0.18;
      const defCh4 = defTow * defEf;
      const defTco2e = (defCh4 * ch4Gwp) / 1000;
      scope1_wastewater.push({
        name: 'Hệ thống bể tự hoại nhà máy',
        tow: Math.round(defTow).toLocaleString('vi-VN'),
        s: '0',
        r: '0',
        ef_ww: '0,18',
        ch4_kg: defCh4.toFixed(2).replace('.', ','),
        gwp: ch4Gwp.toString().replace('.', ','),
        t_co2e: defTco2e.toFixed(2).replace('.', ',')
      });
    }

    const scope2_grid = Array.from(scope2Map.values()).map(row => ({
      name: row.name,
      consumption_kwh: row.amount_sum.toLocaleString('vi-VN'),
      ef_grid: typeof row.ef_grid === 'number' ? row.ef_grid.toString().replace('.', ',') : efInfo.factorComma,
      t_co2e: row.t_co2e_sum.toFixed(2).replace('.', ',')
    }));

    const tbl_317 = Array.from(tbl317Map.values());
    const tbl_318 = Array.from(tbl318Map.values());

    // Tinh tong hop Scope 1
    let sumS1_co2 = 0;
    let sumS1_ch4 = 0;
    let sumS1_n2o = 0;
    let sumS1_tco2e = 0;

    stationaryMap.forEach(r => {
      sumS1_co2 += r.t_co2_sum;
      sumS1_ch4 += r.t_ch4_sum;
      sumS1_n2o += r.t_n2o_sum;
      sumS1_tco2e += r.t_co2e_sum;
    });
    mobileMap.forEach(r => {
      sumS1_co2 += r.t_co2_sum;
      sumS1_ch4 += r.t_ch4_sum;
      sumS1_n2o += r.t_n2o_sum;
      sumS1_tco2e += r.t_co2e_sum;
    });
    pcccMap.forEach(r => {
      sumS1_co2 += r.t_co2;
      sumS1_tco2e += r.t_co2;
    });
    fugitiveMap.forEach(r => {
      sumS1_tco2e += r.t_co2e_sum;
    });
    wastewaterMap.forEach(r => {
      sumS1_tco2e += r.t_co2e_sum;
      sumS1_ch4 += (r.t_co2e_sum / 27.9);
    });

    let sumS2_tco2e = 0;
    scope2Map.forEach(r => {
      sumS2_tco2e += r.t_co2e_sum;
    });

    const sumTotal_tco2e = sumS1_tco2e + sumS2_tco2e;
    const s1_pct = sumTotal_tco2e > 0 ? ((sumS1_tco2e / sumTotal_tco2e) * 100).toFixed(2) : "0,00";
    const s2_pct = sumTotal_tco2e > 0 ? ((sumS2_tco2e / sumTotal_tco2e) * 100).toFixed(2) : "0,00";

    // Danh sach cong trinh (Bảng 2.1)
    const facilities_list = [
      { i: 1, name: 'Khu vực xưởng sản xuất chính', area: '45.000 m²' },
      { i: 2, name: 'Khu vực kho nguyên liệu & thành phẩm', area: '18.500 m²' },
      { i: 3, name: 'Khu nhà văn phòng điều hành & nhà ăn', area: '2.500 m²' },
      { i: 4, name: 'Trạm biến áp & trạm bơm PCCC', area: '1.200 m²' },
      { i: 5, name: 'Trạm xử lý nước thải & hạ tầng kỹ thuật', area: '2.800 m²' }
    ];

    // Danh sach nguon phat thai tong hop (Bảng 2.2)
    const emission_sources = [];
    if (stationaryMap.size > 0) {
      emission_sources.push({ scope: 'Phạm vi 1: Trực tiếp', source_type: '1.1. Đốt cố định', equipment_fuel: 'Lò nung, lò nấu chảy, máy phát điện (FO, DO, Khí)', description: 'Hoạt động đốt nhiên liệu tại các thiết bị cố định' });
    }
    if (mobileMap.size > 0) {
      emission_sources.push({ scope: 'Phạm vi 1: Trực tiếp', source_type: '1.2. Đốt di động', equipment_fuel: 'Đội xe nâng hàng, xe vận tải nội bộ (Dầu DO)', description: 'Nhiên liệu đốt cho phương tiện di chuyển nội bộ' });
    }
    if (fugitiveMap.size > 0) {
      emission_sources.push({ scope: 'Phạm vi 1: Trực tiếp', source_type: '1.3. Rò rỉ môi chất lạnh', equipment_fuel: 'Hệ thống Chiller làm mát xưởng (Gas lạnh)', description: 'Rò rỉ môi chất trong quá trình vận hành và bảo dưỡng' });
    }
    if (pcccMap.size > 0) {
      emission_sources.push({ scope: 'Phạm vi 1: Trực tiếp', source_type: '1.4. Bình PCCC CO2', equipment_fuel: 'Hệ thống bình chữa cháy CO2 xách tay MT3, MT5', description: 'Rò rỉ định kỳ từ bình chữa cháy khí CO2' });
    }
    if (wastewaterMap.size > 0) {
      emission_sources.push({ scope: 'Phạm vi 1: Trực tiếp', source_type: '1.5. Xử lý nước thải', equipment_fuel: 'Hệ thống bể tự hoại & trạm xử lý nước thải', description: 'Phân hủy kỵ khí chất hữu cơ phát sinh khí CH4' });
    }
    if (scope2Map.size > 0) {
      emission_sources.push({ scope: 'Phạm vi 2: Gián tiếp', source_type: '2.1. Điện mua ngoài', equipment_fuel: 'Toàn bộ máy móc sản xuất và phụ trợ', description: 'Điện năng mua từ lưới điện quốc gia (EVN)' });
    }

    // Danh sach may moc thiet bi (Phụ lục 01)
    const equipment_list = [];
    let eqIdx = 1;
    scope2Map.forEach(r => {
      equipment_list.push({ i: eqIdx++, name: r.name, quantity: '1 cụm', power_kw: 'Công suất lớn (Điện lưới)' });
    });
    stationaryMap.forEach(r => {
      equipment_list.push({ i: eqIdx++, name: r.name, quantity: '1 hệ thống', power_kw: 'Đốt nhiên liệu' });
    });
    mobileMap.forEach(r => {
      equipment_list.push({ i: eqIdx++, name: r.name, quantity: '1 đội', power_kw: 'Động cơ đốt trong' });
    });
    fugitiveMap.forEach(r => {
      equipment_list.push({ i: eqIdx++, name: r.name, quantity: '1 cụm', power_kw: 'Hệ thống lạnh Chiller' });
    });

    // Danh sach hoa don dien (Phụ lục 03)
    const invoice_list = [];
    for (let m = 1; m <= 12; m++) {
      const monthKwh = Math.round(Array.from(scope2Map.values()).reduce((s, r) => s + r.amount_sum, 0) / 12);
      invoice_list.push({
        i: m,
        month: m < 10 ? '0' + m : '' + m,
        kwh: monthKwh.toLocaleString('vi-VN')
      });
    }

    return {
      scope1_stationary,
      scope1_mobile,
      scope1_combustion,
      scope1_fugitive,
      scope1_pccc,
      scope1_wastewater,
      scope2_grid,
      tbl_317,
      tbl_318,
      facilities_list,
      emission_sources,
      equipment_list,
      invoice_list,
      uncertainty_pct: (total_uncertainty * 100).toFixed(2).replace('.', ','),
      
      // Summary values
      scope1_co2: sumS1_co2.toFixed(2).replace('.', ','),
      scope1_ch4: sumS1_ch4.toFixed(4).replace('.', ','),
      scope1_ch4_co2e: (sumS1_ch4 * 27.9).toFixed(2).replace('.', ','),
      scope1_n2o: sumS1_n2o.toFixed(5).replace('.', ','),
      scope1_n2o_co2e: (sumS1_n2o * 273).toFixed(2).replace('.', ','),
      scope1_hfc_co2e: Array.from(fugitiveMap.values()).reduce((s, r) => s + r.t_co2e_sum, 0).toFixed(2).replace('.', ','),
      fugitive_total: Array.from(fugitiveMap.values()).reduce((s, r) => s + r.t_co2e_sum, 0).toFixed(2).replace('.', ','),
      scope1_total: sumS1_tco2e.toFixed(2).replace('.', ','),
      scope1_pct: s1_pct.replace('.', ','),

      scope2_co2: sumS2_tco2e.toFixed(2).replace('.', ','),
      scope2_total: sumS2_tco2e.toFixed(2).replace('.', ','),
      scope2_pct: s2_pct.replace('.', ','),

      total_co2: (sumS1_co2 + sumS2_tco2e).toFixed(2).replace('.', ','),
      total_ch4: sumS1_ch4.toFixed(4).replace('.', ','),
      total_ch4_co2e: (sumS1_ch4 * 27.9).toFixed(2).replace('.', ','),
      total_n2o: sumS1_n2o.toFixed(5).replace('.', ','),
      total_n2o_co2e: (sumS1_n2o * 273).toFixed(2).replace('.', ','),
      total_hfc_co2e: Array.from(fugitiveMap.values()).reduce((s, r) => s + r.t_co2e_sum, 0).toFixed(2).replace('.', ','),
      biogenic_total: sumBiogenic_tco2.toFixed(2).replace('.', ','),
      scope1_biogenic: sumBiogenic_tco2.toFixed(2).replace('.', ','),
      total_emissions: sumTotal_tco2e.toFixed(2).replace('.', ','),

      // BOD & Nuoc thai sinh hoat (Bang 3.8 & 3.14)
      ww_employees: Math.round(ww_emp).toLocaleString('vi-VN'),
      ww_hours: ww_hours.toString(),
      ww_days: ww_days.toString(),
      ww_bod_conc: ww_bod_conc.toString(),
      ww_bod_per_person_year: ww_bod_per_person_year.toFixed(2).replace('.', ','),
      ww_i_factor: ww_i_factor.toFixed(2).replace('.', ','),
      ww_tow: Math.round(totalWwTow).toLocaleString('vi-VN'),
      ww_tech_type: 'Bể tự hoại (Septic tank)',
      ww_b0: '0,60',
      ww_mcf: '0,50',
      ww_ef: (0.60 * 0.50).toFixed(2).replace('.', ',')
    };
  },

  exportReport(companyInfo, calcResults, reportYear, activitiesOverride) {
    if (!companyInfo || !companyInfo.name) {
      if (typeof alert !== 'undefined') {
        alert("Vui lòng vào phần 'Thiết lập' điền thông tin Công ty trước khi xuất báo cáo.");
      }
      return;
    }

    try {
      const content = base64ToArrayBuffer(TEMPLATE_BASE64);
      const PizZipLib = (typeof window !== 'undefined' && window.PizZip) ? window.PizZip : require('pizzip');
      const DocxLib = (typeof window !== 'undefined' && window.docxtemplater) ? window.docxtemplater : require('docxtemplater');
      
      const zip = new PizZipLib(content);
      const effectiveReportYear = reportYear || (typeof window !== 'undefined' && typeof window.getActiveReportingYear === 'function' ? window.getActiveReportingYear() : '2026');
      const efInfo = resolveGridEFInfo(effectiveReportYear);

      // Cap nhat dong he so phat thai luoi dien & cong van trong word/document.xml theo nam bao cao
      const docXmlFile = zip.file('word/document.xml');
      if (docXmlFile) {
        let docXml = docXmlFile.asText();
        docXml = docXml
          .replace(
            /<w:p w14:paraId="08693D2F"[\s\S]*?<\/w:p>/,
            `<w:p w14:paraId="08693D2F" w14:textId="77777777" w:rsidR="00500A4B" w:rsidRDefault="006D437B"><w:pPr><w:pStyle w:val="TableParagraph"/><w:spacing w:before="210"/><w:ind w:left="106"/><w:rPr><w:sz w:val="26"/></w:rPr></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/><w:sz w:val="26"/><w:szCs w:val="26"/></w:rPr><w:t>${efInfo.doc}</w:t></w:r></w:p>`
          )
          .replace(
            /<w:p w14:paraId="55990FC9"[\s\S]*?<\/w:p>/,
            `<w:p w14:paraId="55990FC9" w14:textId="77777777" w:rsidR="00500A4B" w:rsidRDefault="006D437B"><w:pPr><w:pStyle w:val="TableParagraph"/><w:ind w:right="128"/><w:jc w:val="right"/><w:rPr><w:sz w:val="26"/></w:rPr></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/><w:sz w:val="26"/><w:szCs w:val="26"/></w:rPr><w:t>${efInfo.factorComma}</w:t></w:r></w:p>`
          )
          .replace(
            /<w:p w14:paraId="4BD2B0D3"[\s\S]*?<\/w:p>/,
            `<w:p w14:paraId="4BD2B0D3" w14:textId="77777777" w:rsidR="00500A4B" w:rsidRDefault="006D437B"><w:pPr><w:pStyle w:val="TableParagraph"/><w:spacing w:before="31" w:line="390" w:lineRule="atLeast"/><w:ind w:left="102" w:right="311"/><w:rPr><w:sz w:val="26"/></w:rPr></w:pPr><w:r><w:rPr><w:rFonts w:ascii="Times New Roman" w:hAnsi="Times New Roman" w:cs="Times New Roman"/><w:sz w:val="26"/><w:szCs w:val="26"/></w:rPr><w:t>${efInfo.doc}</w:t></w:r></w:p>`
          );
        zip.file('word/document.xml', docXml);
      }

      const doc = new DocxLib(zip, {
        paragraphLoop: true,
        linebreaks: true,
      });

      let activities = [];
      if (activitiesOverride && Array.isArray(activitiesOverride)) {
        activities = activitiesOverride;
      } else if (calcResults && Array.isArray(calcResults.activities)) {
        activities = calcResults.activities;
      } else if (typeof window !== 'undefined' && window.__exportActivitiesOverride) {
        activities = window.__exportActivitiesOverride;
      } else if (typeof localStorage !== 'undefined') {
        const userStr = (localStorage.getItem('gs_current_user') || 'guest').trim();
        const userSlug = userStr.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '') || 'guest';
        const branchSelect = (typeof document !== 'undefined') ? document.getElementById('branch-selector') : null;
        if (branchSelect) {
          const branchName = branchSelect.value || 'main';
          const branchKey = branchName.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '') || 'main';
          const storageKey = `gs_data_${userSlug}_${branchKey}_activity`;
          const rawKey = `gs_data_${userStr}_${branchKey}_activity`;
          activities = JSON.parse(localStorage.getItem(storageKey) || localStorage.getItem(rawKey) || '[]');
          if (activities.length === 0) {
            const candKeys = [`gs_data_${userSlug}_tru_so_chinh_activity`, `gs_data_${userStr}_tru_so_chinh_activity`];
            for (const ck of candKeys) {
              const cand = JSON.parse(localStorage.getItem(ck) || '[]');
              if (cand.length > 0) { activities = cand; break; }
            }
          }
        } else {
          activities = JSON.parse(localStorage.getItem(`gs_data_${userSlug}_tru_so_chinh_activity`) || localStorage.getItem('gs_v2_activity_main') || '[]');
        }
        if (activities.length === 0) {
          const old = JSON.parse(localStorage.getItem('gs_v2_activity_main')) || [];
          if (old.length > 0) activities = old;
        }
      }

      const grouped = this.groupActivities(activities, effectiveReportYear);

      const data = {
        company_name: companyInfo.name,
        tax: companyInfo.tax || "0101234567",
        license: companyInfo.license || "Số: 0101234567 do Sở Kế hoạch và Đầu tư cấp",
        investment_cert: companyInfo.investmentCert || "Giấy chứng nhận đầu tư số: 6868686868",
        founded_year: companyInfo.foundedYear || "2018",
        address: companyInfo.address || "Việt Nam",
        manager_agency: companyInfo.managerAgency || "UBND Tỉnh / Sở Tài nguyên và Môi trường",
        gps: companyInfo.gps || "N/A",
        phone: companyInfo.phone || "N/A",
        email: companyInfo.email || "info@company.com.vn",
        website: companyInfo.website || "www.company.com.vn",
        industry: companyInfo.industry || "Sản xuất kim loại và luyện kim (Thép / Nhôm)",

        rep_name: companyInfo.repName || "Nguyễn Văn Kiểm Kê",
        rep_title: companyInfo.repTitle || "Tổng Giám Đốc",
        rep_phone: companyInfo.repPhone || "N/A",
        rep_email: companyInfo.repEmail || "N/A",

        desc_boundary: companyInfo.descBoundary || "Toàn bộ khuôn viên nhà máy và các phân xưởng sản xuất",
        desc_process: companyInfo.descProcess || (typeof getIndustryProcessPreset === 'function' ? getIndustryProcessPreset(companyInfo.industry) : null) || "Quy trình sản xuất khép kín từ tiếp nhận nguyên liệu, gia công chế tạo đến đóng gói thành phẩm",
        desc_waste: companyInfo.descWaste || "Hệ thống xử lý nước thải sinh hoạt và chất thải rắn đạt quy chuẩn QCVN",

        total_emissions: grouped.total_emissions,
        scope1_total: grouped.scope1_total,
        scope2_total: grouped.scope2_total,
        biogenic_total: (grouped.biogenic_total && grouped.biogenic_total !== "0,00") ? grouped.biogenic_total : (calcResults && calcResults.biogenic ? calcResults.biogenic.toFixed(2).replace('.', ',') : "0,00"),
        scope1_biogenic: (grouped.scope1_biogenic && grouped.scope1_biogenic !== "0,00") ? grouped.scope1_biogenic : "0,00",
        
        scope1_co2: grouped.scope1_co2,
        scope1_ch4: grouped.scope1_ch4,
        scope1_ch4_co2e: grouped.scope1_ch4_co2e,
        scope1_n2o: grouped.scope1_n2o,
        scope1_n2o_co2e: grouped.scope1_n2o_co2e,
        scope1_hfc_co2e: grouped.scope1_hfc_co2e,
        fugitive_total: grouped.fugitive_total,
        scope1_pct: grouped.scope1_pct,

        scope2_co2: grouped.scope2_co2,
        scope2_pct: grouped.scope2_pct,

        total_co2: grouped.total_co2,
        total_ch4: grouped.total_ch4,
        total_ch4_co2e: grouped.total_ch4_co2e,
        total_n2o: grouped.total_n2o,
        total_n2o_co2e: grouped.total_n2o_co2e,
        total_hfc_co2e: grouped.total_hfc_co2e,

        reportYear: reportYear || "2026",
        scope1_stationary: grouped.scope1_stationary,
        scope1_mobile: grouped.scope1_mobile,
        scope1_fugitive: grouped.scope1_fugitive,
        scope1_pccc: grouped.scope1_pccc,
        scope1_wastewater: grouped.scope1_wastewater,
        scope1_combustion: grouped.scope1_combustion,
        scope2_grid: grouped.scope2_grid,
        tbl_317: grouped.tbl_317,
        tbl_318: grouped.tbl_318,
        facilities_list: grouped.facilities_list,
        emission_sources: grouped.emission_sources,
        equipment_list: grouped.equipment_list,
        invoice_list: grouped.invoice_list,
        uncertainty_pct: grouped.uncertainty_pct,

        // Bang 3.8 & Bang 3.14 (Nuoc thai & BOD)
        ww_employees: grouped.ww_employees,
        ww_hours: grouped.ww_hours,
        ww_days: grouped.ww_days,
        ww_bod_conc: grouped.ww_bod_conc,
        ww_bod_per_person_year: grouped.ww_bod_per_person_year,
        ww_i_factor: grouped.ww_i_factor,
        ww_tow: grouped.ww_tow,
        ww_tech_type: grouped.ww_tech_type,
        ww_b0: grouped.ww_b0,
        ww_mcf: grouped.ww_mcf,
        ww_ef: grouped.ww_ef
      };

      doc.render(data);

      if (typeof window !== 'undefined' && typeof saveAs !== 'undefined') {
        const out = doc.getZip().generate({
          type: "blob",
          mimeType: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        });
        saveAs(out, `Bao_Cao_KNK_${companyInfo.name}_${reportYear}.docx`);
      }

      return doc;
      
    } catch (error) {
      console.error("Lỗi khi tạo file Word:", error);
      if (typeof alert !== 'undefined') {
        alert("Lỗi tạo file Word: " + error.message);
      }
      throw error;
    }
  }
};

if (typeof window !== 'undefined') {
  window.WordExport = WordExport;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = WordExport;
}
